#include <cuda_runtime.h>
#include <vector>
#include <fstream>
#include <chrono>
#include <filesystem>
#include <cstring>
#include "process.cu"
#include "study_params.h"
#define C(x) CUDA_CHECK_RETURN(x)
template<class A>std::vector<A> read(const std::string&p,int n){std::ifstream f(p,std::ios::binary);std::vector<A>a(n);f.read((char*)a.data(),n*sizeof(A));if(f.gcount()!=n*sizeof(A))exit(2);return a;}
template<class A>struct Buffer{A*base;A*ptr;std::vector<A>initial;Buffer(std::vector<A>a,A guard){initial.assign(16,guard);initial.insert(initial.end(),a.begin(),a.end());initial.insert(initial.end(),16,guard);C(cudaMalloc(&base,initial.size()*sizeof(A)));ptr=base+16;reset();}void reset(){C(cudaMemcpy(base,initial.data(),initial.size()*sizeof(A),cudaMemcpyHostToDevice));}void append(std::vector<double>&a){std::vector<A>v(initial.size());C(cudaMemcpy(v.data(),base,v.size()*sizeof(A),cudaMemcpyDeviceToHost));for(A x:v)a.push_back(x);}~Buffer(){cudaFree(base);}};
struct Work{int group,set;Buffer<int>ref,q,dot,count;Buffer<float>random,scores;std::vector<int>hd,hc;double dotSum,average,above,pvalue,enfp,significant;float threshold;Work(int k):group(k),set(k==0?2:1),ref(read<int>("ref"+std::to_string(k)+"_i32.bin",N),1234567),q(read<int>("query_i32.bin",N),1234567),dot(std::vector<int>(DB,0),-12345),count(std::vector<int>(SB,0),-12345),random(read<float>("random"+std::to_string(k)+"_f32.bin",M),-999),scores(std::vector<float>(R,0),-999),hd(DB),hc(SB){}void reset(){ref.reset();q.reset();random.reset();dot.reset();scores.reset();count.reset();}void prefix(std::vector<double>&a){a.insert(a.end(),{N,R,SIG,double(set),UC,DB,SB});ref.append(a);q.append(a);random.append(a);dot.append(a);scores.append(a);count.append(a);}void pipeline(){computeDotProductHelper<<<DB,T,T*sizeof(int)>>>(dot.ptr,ref.ptr,q.ptr,N);C(cudaGetLastError());C(cudaMemcpy(hd.data(),dot.ptr,DB*sizeof(int),cudaMemcpyDeviceToHost));dotSum=0;for(int x:hd)dotSum+=x;average=(dotSum/double(UC))/set;threshold=average;computeRandomConnectionScores<<<SB,T>>>(random.ptr,ref.ptr,scores.ptr,M,float(UC),set,R);C(cudaGetLastError());countAboveThresholdHelper<<<SB,T,T*sizeof(int)>>>(scores.ptr,threshold,count.ptr,R);C(cudaGetLastError());C(cudaMemcpy(hc.data(),count.ptr,SB*sizeof(int),cudaMemcpyDeviceToHost));above=0;for(int x:hc)above+=x;pvalue=computePValueHelper(above,R);enfp=pvalue*getNDrugs(1);significant=enfp<1;}void tail(std::vector<double>&a){dot.append(a);scores.append(a);count.append(a);a.insert(a.end(),{dotSum,average,double(threshold),above,pvalue,enfp,significant});}};
int main(int argc,char**argv){auto expected=read<double>(argv[1],COUNT);Work a(0),b(1);auto pipeline=[&](){a.pipeline();b.pipeline();C(cudaDeviceSynchronize());};pipeline();for(int t=1;t<=5;t++){a.reset();b.reset();std::vector<double>out;a.prefix(out);b.prefix(out);if(out.size()!=PREFIX)return 3;C(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();pipeline();double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();a.tail(out);b.tail(out);bool good=out.size()==COUNT;double error=0;for(int i=0;i<COUNT;i++){good=good&&std::isfinite(out[i])&&out[i]==expected[i];error=std::max(error,std::abs(out[i]-expected[i]));}std::string path=std::string(getenv("STUDY_OUTPUT_DIR"))+"/cm_trial"+std::to_string(t)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)out.data(),out.size()*8);f.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"max_rel_error\":null,\"jit_excluded\":true,\"timing_region\":\"resident_two_drugsets_3GPUstages_dot_hostfeedback_count_hostpvalue\",\"internal_repeats\":1,\"iterations\":1,\"kernel_launches\":6,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",t,seconds,good?"true":"false",out.size(),error,path.c_str(),out.size());fflush(stdout);if(!good)return 4;}return 0;}
